using System;
using System.Collections.Generic;
using System.Text;

namespace OnlyWorlds.Sdk
{
    /// <summary>
    /// Unicode NFC at the version folder spec §4.7 (OW-18) pins, built from Unicode's own files
    /// (<see cref="OWNfcData"/>, generated by <c>tools/gen_nfc.py</c>), never from the runtime: the first half of the
    /// one fold every <c>.owworld</c> reader uses, before <see cref="OWCaseFold"/>.
    /// </summary>
    /// <remarks>
    /// <para>
    /// Not <c>string.Normalize</c>: that answers from the runtime's own tables (Mono's, IL2CPP's and .NET's differ),
    /// and a runtime on Unicode 16 decomposes U+11383, which 15.1 leaves unassigned, so it joins two names the pinned
    /// version keeps apart (the set's <c>pass-OW-18-nfc-unassigned</c>).
    /// </para>
    /// <para>
    /// UAX #15: decompose canonically (UnicodeData field 5, applied until nothing changes; Hangul by arithmetic), put
    /// each run of non-starters in order of class (a stable sort), then recompose: a code point joins the last starter
    /// when nothing between them blocks it and the pair is a primary composite, a two-part decomposition outside
    /// Full_Composition_Exclusion (CompositionExclusions' list, plus the singletons and non-starter decompositions its
    /// comments derive from UnicodeData). <c>OWNfcTests</c> runs Unicode's NormalizationTest-15.1.0.txt through it.
    /// </para>
    /// </remarks>
    internal static class OWNfc
    {
        private const int SBase = 0xAC00, LBase = 0x1100, VBase = 0x1161, TBase = 0x11A7;
        private const int LCount = 19, VCount = 21, TCount = 28;
        private const int NCount = VCount * TCount, SCount = LCount * NCount;

        /// <summary>
        /// The string's NFC. A string whose every UTF-16 unit is below <see cref="OWNfcData.StableBelow"/> is its own
        /// NFC and comes back as it is, with no table touched.
        /// </summary>
        /// <exception cref="ArgumentException">The string is not valid UTF-16 (a lone surrogate), as
        /// <c>string.Normalize</c> refuses it.</exception>
        internal static string Normalize(string text)
        {
            if (string.IsNullOrEmpty(text)) return text;

            var at = 0;
            while (at < text.Length && text[at] < OWNfcData.StableBelow) at++;
            if (at == text.Length) return text;

            var cps = new List<int>(text.Length + 4);
            for (var i = 0; i < text.Length; i++)
            {
                int cp = text[i];
                if (char.IsHighSurrogate(text[i]) && i + 1 < text.Length && char.IsLowSurrogate(text[i + 1]))
                {
                    cp = char.ConvertToUtf32(text[i], text[i + 1]);
                    i++;
                }
                else if (char.IsSurrogate(text[i]))
                {
                    throw new ArgumentException($"A lone surrogate at index {i}: not valid UTF-16.", nameof(text));
                }

                Decompose(cp, cps);
            }

            Reorder(cps);
            Compose(cps);

            var built = new StringBuilder(cps.Count + 4);
            foreach (var cp in cps)
            {
                if (cp <= 0xFFFF) built.Append((char)cp);
                else built.Append(char.ConvertFromUtf32(cp));
            }

            return built.ToString();
        }

        /// <summary>A code point's canonical combining class (UnicodeData field 3): 0 when the file names none.</summary>
        internal static int CombiningClass(int cp)
        {
            if (cp < OWNfcData.StableBelow) return 0;
            var at = Array.BinarySearch(OWNfcData.ClassCodePoints, cp);
            return at >= 0 ? OWNfcData.Classes[at] : 0;
        }

        /// <summary>Full_Composition_Exclusion as derived here, ascending (for the tests' digest).</summary>
        internal static int[] FullCompositionExclusion()
        {
            var all = new int[Tables.Excluded.Count];
            Tables.Excluded.CopyTo(all);
            Array.Sort(all);
            return all;
        }

        /// <summary>Every primary composite as derived here, ascending by the composite: first, second, composite.</summary>
        internal static int[] PrimaryComposites()
        {
            var triples = new List<int[]>();
            foreach (var pair in Tables.Composites) triples.Add(new[] { (int)(pair.Key >> 21), (int)(pair.Key & 0x1FFFFF), pair.Value });
            triples.Sort((a, b) => a[2].CompareTo(b[2]));
            var flat = new int[triples.Count * 3];
            for (var i = 0; i < triples.Count; i++) Array.Copy(triples[i], 0, flat, i * 3, 3);
            return flat;
        }

        /// <summary>Appends <paramref name="cp"/>'s full canonical decomposition.</summary>
        private static void Decompose(int cp, List<int> into)
        {
            var s = cp - SBase;
            if (s >= 0 && s < SCount)
            {
                into.Add(LBase + s / NCount);
                into.Add(VBase + s % NCount / TCount);
                if (s % TCount != 0) into.Add(TBase + s % TCount);
                return;
            }

            if (Tables.Full.TryGetValue(cp, out var full)) into.AddRange(full);
            else into.Add(cp);
        }

        /// <summary>Canonical ordering: each run of non-starters sorted by class, stably (an insertion sort).</summary>
        private static void Reorder(List<int> cps)
        {
            for (var i = 1; i < cps.Count; i++)
            {
                var c = cps[i];
                var cc = CombiningClass(c);
                if (cc == 0) continue;

                var j = i;
                while (j > 0 && CombiningClass(cps[j - 1]) > cc)
                {
                    cps[j] = cps[j - 1];
                    j--;
                }

                cps[j] = c;
            }
        }

        /// <summary>
        /// Canonical composition, in place: each code point joins the last starter when it is not blocked from it (no
        /// code point between them of class 0 or of a class not below its own) and the two are a primary composite.
        /// </summary>
        /// <remarks>
        /// A starter that does not compose becomes the new last starter, so only non-starters ever sit between; they
        /// are in canonical order, so the last one kept has the highest class of them, and the code point is blocked
        /// exactly when that class is not below its own. With nothing between (<c>last</c> is -1) it is never blocked.
        /// </remarks>
        private static void Compose(List<int> cps)
        {
            var kept = 0;
            var starter = -1;
            var last = -1; // the class of the last code point kept after the starter; -1 when none is
            for (var i = 0; i < cps.Count; i++)
            {
                var c = cps[i];
                var cc = CombiningClass(c);
                if (starter >= 0 && last < cc)
                {
                    var composite = ComposePair(cps[starter], c);
                    if (composite >= 0)
                    {
                        cps[starter] = composite;
                        continue;
                    }
                }

                if (cc == 0)
                {
                    starter = kept;
                    last = -1;
                }
                else
                {
                    last = cc;
                }

                cps[kept++] = c;
            }

            cps.RemoveRange(kept, cps.Count - kept);
        }

        /// <summary>The primary composite of a starter and the next code point, or -1. Hangul by arithmetic.</summary>
        private static int ComposePair(int a, int b)
        {
            if (a >= LBase && a < LBase + LCount && b >= VBase && b < VBase + VCount)
                return SBase + ((a - LBase) * VCount + (b - VBase)) * TCount;

            var s = a - SBase;
            if (s >= 0 && s < SCount && s % TCount == 0 && b > TBase && b < TBase + TCount) return a + (b - TBase);

            return Tables.Composites.TryGetValue(Key(a, b), out var composite) ? composite : -1;
        }

        private static long Key(int a, int b) => ((long)a << 21) | (uint)b;

        /// <summary>
        /// What <see cref="OWNfcData"/>'s facts derive to, built at the first string that needs them (so a name the
        /// fast path answers never builds them).
        /// </summary>
        private static class Tables
        {
            /// <summary>Each decomposable code point's full canonical decomposition (field 5 until nothing changes).</summary>
            internal static readonly Dictionary<int, int[]> Full = new Dictionary<int, int[]>();

            /// <summary>
            /// Full_Composition_Exclusion: CompositionExclusions' listed code points, plus singletons (a decomposition
            /// of one code point) and non-starter decompositions (the code point, or its decomposition's first part,
            /// of a class other than 0), the two its comments derive from UnicodeData.
            /// </summary>
            internal static readonly HashSet<int> Excluded = new HashSet<int>(OWNfcData.ListedExclusions);

            /// <summary>The primary composites: a two-part decomposition outside <see cref="Excluded"/>, keyed by its parts.</summary>
            internal static readonly Dictionary<long, int> Composites = new Dictionary<long, int>();

            static Tables()
            {
                var codes = OWNfcData.DecompositionCodePoints;
                var first = OWNfcData.DecompositionFirst;
                var second = OWNfcData.DecompositionSecond;

                for (var i = 0; i < codes.Length; i++)
                {
                    if (second[i] < 0 || CombiningClass(codes[i]) != 0 || CombiningClass(first[i]) != 0)
                        Excluded.Add(codes[i]);
                }

                var expanded = new List<int>(8);
                for (var i = 0; i < codes.Length; i++)
                {
                    expanded.Clear();
                    Expand(first[i], expanded);
                    if (second[i] >= 0) Expand(second[i], expanded);
                    Full[codes[i]] = expanded.ToArray();

                    if (second[i] >= 0 && !Excluded.Contains(codes[i])) Composites[Key(first[i], second[i])] = codes[i];
                }
            }

            private static void Expand(int cp, List<int> into)
            {
                var at = Array.BinarySearch(OWNfcData.DecompositionCodePoints, cp);
                if (at < 0)
                {
                    into.Add(cp);
                    return;
                }

                Expand(OWNfcData.DecompositionFirst[at], into);
                if (OWNfcData.DecompositionSecond[at] >= 0) Expand(OWNfcData.DecompositionSecond[at], into);
            }
        }
    }
}
